function unpack() {
  const raw = PAYLOAD.replace(/\s+/g, '');
  return JSON.parse(gunzipSync(Buffer.from(raw, 'base64')).toString('utf8'));
}

// --- Install -----------------------------------------------------------------

function main() {
  console.log('');
  console.log(bold('  Visa Agentic Mandate Manager'));
  console.log(dim(`  installing into ${TARGET}`));
  if (DRY_RUN) console.log(amber('  dry run - nothing will be written'));
  console.log('');

  let files;
  try {
    files = unpack();
  } catch (error) {
    console.error(red(`  Payload could not be read: ${error.message}`));
    console.error(dim('  The file may have been truncated or re-wrapped in transit.'));
    process.exit(1);
  }

  const paths = Object.keys(files).sort();

  if (!existsSync(join(TARGET, '.git'))) {
    console.log(amber('  ! No .git here. Check you are in the repository root before continuing.'));
    console.log(dim(`    Current target: ${TARGET}`));
    console.log('');
  }

  const moved = [];
  const backedUp = [];
  const written = [];
  const skipped = [];

  // 1. Relocate the previous implementation.
  if (!KEEP_LEGACY) {
    for (const rel of SUPERSEDED) {
      const from = join(TARGET, rel);
      if (!existsSync(from)) continue;
      const to = join(TARGET, 'legacy', rel);
      if (!DRY_RUN) {
        mkdirSync(dirname(to), { recursive: true });
        renameSync(from, to);
      }
      moved.push(`${rel} -> legacy/${rel}`);
    }
  }

  // 2 + 3. Write the new tree, backing up anything already there.
  for (const rel of paths) {
    if (PROTECTED.some((p) => rel === p || rel.startsWith(`${p}/`))) {
      skipped.push(rel);
      continue;
    }

    const dest = join(TARGET, rel.split('/').join(sep));

    if (existsSync(dest)) {
      const identical = (() => {
        try {
          return statSync(dest).size === Buffer.byteLength(files[rel], 'utf8');
        } catch {
          return false;
        }
      })();

      if (!identical && !FORCE) {
        const backup = `${dest}.bak-${stamp}`;
        if (!DRY_RUN) copyFileSync(dest, backup);
        backedUp.push(rel);
      }
    }

    if (!DRY_RUN) {
      mkdirSync(dirname(dest), { recursive: true });
      writeFileSync(dest, files[rel], 'utf8');
    }
    written.push(rel);
  }

  // --- Report ----------------------------------------------------------------

  if (moved.length) {
    console.log(bold('  Moved to legacy/'));
    console.log(dim('  Superseded by the new implementation. Kept for your before/after disclosure.'));
    for (const m of moved) console.log(`    ${dim(m)}`);
    console.log('');
  }

  if (backedUp.length) {
    console.log(bold('  Backed up before overwriting'));
    for (const b of backedUp) console.log(`    ${amber(b)}${dim(`.bak-${stamp}`)}`);
    console.log('');
  }

  if (skipped.length) {
    console.log(dim(`  Skipped ${skipped.length} protected path(s)`));
    console.log('');
  }

  const byTop = new Map();
  for (const rel of written) {
    const top = rel.includes('/') ? `${rel.split('/')[0]}/` : 'root';
    byTop.set(top, (byTop.get(top) ?? 0) + 1);
  }

  console.log(bold(`  Wrote ${written.length} files`));
  for (const [top, count] of [...byTop].sort()) {
    console.log(`    ${green(String(count).padStart(3))}  ${top}`);
  }
  console.log('');

  if (DRY_RUN) {
    console.log(amber('  Dry run complete. Re-run without --dry-run to apply.'));
    console.log('');
    return;
  }

  console.log(bold('  Next'));
  console.log(`    1  ${cyan('npm install')}`);
  console.log(`    2  ${cyan('cp .env.example .env')}   ${dim('(Windows: copy .env.example .env)')}`);
  console.log(`    3  set ${cyan('CALLBACK_SIGNING_SECRET')} in .env   ${dim('openssl rand -base64 32')}`);
  console.log(`    4  ${cyan('npm run typecheck && npm test')}   ${dim('expect 60 passing')}`);
  console.log(`    5  ${cyan('npm run dev')}   then open ${cyan('http://localhost:3100/dashboard')}`);
  console.log('');
  console.log(dim('  It runs with zero API keys - unconfigured integrations simulate and say so.'));
  console.log(dim('  AI agents: read AGENTS.md first - context, invariants, setup and the demo runbook.'));
  console.log(dim('  Humans: README.md, then PRAVA_INTEGRATION.md for the sandbox checkout modes.'));
  console.log('');
  console.log(amber('  Your Prava sandbox card belongs in .env only, never in .env.example.'));
  console.log(dim('  Test cards are team-scoped and capped at 30 transactions a day.'));
  console.log('');
}

main();
